"""Build a categorized vocabulary. Entries are words or usable short phrases, not IDs.

Only the scene category expands curated places with compatible scene descriptions;
all other entries below are curated independently. Runtime has no build dependency.
"""
import json
from pathlib import Path

categories = []


def add(key, label, words, scopes=None, kind='entity'):
    words = list(dict.fromkeys(words.split('|') if isinstance(words, str) else words))
    categories.append(dict(id=key, label=label, kind=kind, scopes=scopes or [], words=words))


