for i, (scope, words) in enumerate(themes.items()):
    add(f'theme-{i+1:02}', f'{scope} · 侧重', words, [scope], 'theme')

# Do not replace an image character's job with an unrelated job in its shop.
next(group for group in categories if group['id'] == 'jobs-service')['scopes'] = ['故事写作']
# Keep the grammatical action of wearing accessories/clothing compatible.
categories = [group for group in categories if group['id'] != 'clothes']
add('scarves', '围巾与领巾', '围巾|丝巾|领巾|头巾|围脖|羊毛围巾|棉麻围巾|针织围巾|条纹围巾|格纹围巾|波点丝巾|印花丝巾|纯色领巾|方形丝巾|长条丝巾|小方巾|三角领巾|手织围巾|粗针围巾|流苏围巾', ['图片创作', '故事写作'])
add('hats', '帽子', '毛线帽|贝雷帽|渔夫帽|草帽|礼帽|鸭舌帽|棒球帽|宽檐帽|圆顶帽|针织帽|报童帽|水手帽|画家帽|软呢帽|藤编帽|遮阳帽|登山帽|灯芯绒帽|编织草帽|羊毛毡帽', ['图片创作', '故事写作'])
add('garments', '衣装', '斗篷|雨衣|外套|风衣|大衣|夹克|针织衫|毛衣|开衫|背心|马甲|衬衫|短袖衬衫|长袖衬衫|连帽衫|卫衣|连衣裙|背带裙|百褶裙|半身裙|工装裤|背带裤|短裤|长裤|工作服', ['图片创作', '故事写作'])

# These are usable location phrases rather than a Cartesian product of random
# adjectives and nouns. Each prefix is suitable for every place in this list.
places = '海边小书店|河畔咖啡馆|山间旅馆|街角花店|巷口面包店|小镇邮局|湖边小屋|老城照相馆|社区图书馆|森林木屋|山顶天文台|海港灯塔|玻璃温室|街边画室|木工工作室|旧式电车站|城市屋顶花园|乡间火车站|小镇钟表店|河边陶艺坊|老街杂货铺|独立唱片店|港口鱼市|社区菜市场|湖畔茶室|小巷甜品店|露天音乐台|山路休息亭|古城裁缝铺|运河码头|旧式电影院|乡村磨坊|谷仓工作室|城市观鸟亭|山谷露营地|海岛气象站|旧砖厂展厅|庭院餐厅|林间阅读亭|小镇修鞋铺|街角文具店|河湾船屋|山坡果园|海边画廊|社区共享厨房|草地野餐区|石桥旁的茶馆|坡道上的民宿|小广场喷泉|旧仓库剧场'.split('|')
prefixes = ['雨后的', '晨光中的', '暮色中的', '飘着薄雾的', '被树影环绕的', '灯光温暖的']
add('scenes', '画面地点与氛围', places + [prefix + place for place in places for prefix in prefixes], ['图片创作'])

for key, label, unit, values in [
    ('minutes', '时长 · 分钟', '分钟', list(range(2, 61)) + [65, 70, 75, 80, 85, 90, 100, 110, 120, 150, 180]),
    ('hours', '时长 · 小时', '小时', range(1, 25)),
    ('days', '时长 · 天', '天', range(2, 61)),
    ('weeks', '时长 · 周', '周', range(2, 53)),
    ('months', '时长 · 月', '个月', range(2, 25)),
    ('years', '时长 · 年', '年', range(2, 51)),
    ('people', '人数', '人', list(range(2, 21)) + [25, 30, 35, 40, 45, 50, 60, 70, 80, 90, 100]),
    ('area', '空间面积', '平方米', list(range(5, 41)) + [45, 50, 55, 60, 65, 70, 75, 80, 90, 100, 120, 150]),
    ('money', '金额', '元', [5, 8, 10, 12, 15, 18, 20, 25, 30, 35, 40, 45, 50, 60, 70, 80, 90, 100, 120, 150, 180, 200, 250, 300, 350, 400, 450, 500, 600, 700, 800, 900, 1000, 1200, 1500, 1800, 2000, 2500, 3000, 4000, 5000, 8000, 10000]),
    ('count', '数量', '个', list(range(2, 41)) + [45, 50, 60, 70, 80, 90, 100]),
    ('age', '年龄', '岁', range(3, 91)),
    ('steps', '步数', '步', [100, 200, 300, 400, 500, 600, 800, 1000, 1200, 1500, 1800, 2000, 2500, 3000, 3500, 4000, 4500, 5000, 5500, 6000, 6500, 7000, 7500, 8000, 8500, 9000, 9500, 10000, 11000, 12000]),
    ('characters', '文字数量', '字', [50, 60, 80, 100, 120, 150, 180, 200, 250, 300, 350, 400, 450, 500, 600, 700, 800, 900, 1000, 1200, 1500, 1800, 2000, 2500, 3000, 3500, 4000, 4500, 5000, 6000]),
]:
    add('number-' + key, label, [str(value) + unit for value in values], kind='number')

all_words = {word for category in categories for word in category['words']}
count = sum(len(category['words']) for category in categories)
assert len(all_words) > 2000, len(all_words)
result = dict(version=1, description='按语义分类的提示词抖动词库；包含词语与自然短语。', count=count, uniqueCount=len(all_words), categories=categories)
target = Path(__file__).resolve().parents[1] / 'data' / 'jitter-lexicon.js'
target.write_text('// Generated by scripts/generate-lexicon.py; edit the curated source to rebuild.\nexport default ' + json.dumps(result, ensure_ascii=False, indent=2) + ';\n')
target.with_suffix('.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
print(f'{len(categories)} categories, {count} entries, {len(all_words)} unique words/phrases -> {target}')
